"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["9117"],{9502(e,t,s){s.r(t),s.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"m7-packaging/lesson","title":"Lesson: Ship the Model \u2014 KitOps, OCI Artifacts & Signing","description":"Lesson video ~35 min \xb7 Lab ~45\u201360 min hands-on, depending on your machine.","source":"@site/docs/m7-packaging/lesson.md","sourceDirName":"m7-packaging","slug":"/m7-packaging/lesson","permalink":"/305-llmops/docs/m7-packaging/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Ship the Model \u2014 KitOps, OCI Artifacts & Signing"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/305-llmops/docs/m6-fine-tuning/deep-dive"},"next":{"title":"Lab: Ship the Model \u2014 KitOps, OCI Artifacts & Signing","permalink":"/305-llmops/docs/m7-packaging/lab"}}'),n=s(4848),a=s(8453),o=s(7684);let r={sidebar_position:1,title:"Lesson: Ship the Model \u2014 KitOps, OCI Artifacts & Signing"},h="Ship the Model \u2014 KitOps, OCI Artifacts & Signing",d={},l=[{value:"Why a filename is not a version \u2014 the courier without a manifest",id:"why-a-filename-is-not-a-version--the-courier-without-a-manifest",level:2},{value:"What a model actually is on disk (one recap, not a re-teach)",id:"what-a-model-actually-is-on-disk-one-recap-not-a-re-teach",level:2},{value:"OCI artifacts and layers \u2014 the shipping container with a manifest",id:"oci-artifacts-and-layers--the-shipping-container-with-a-manifest",level:2},{value:"ModelKit and the Kitfile \u2014 a Dockerfile for models",id:"modelkit-and-the-kitfile--a-dockerfile-for-models",level:2},{value:"Push, pull, and the crate you actually want",id:"push-pull-and-the-crate-you-actually-want",level:2},{value:"Signing \u2014 the wax seal, not the locked box",id:"signing--the-wax-seal-not-the-locked-box",level:2},{value:"Semver for models \u2014 edition numbers on a textbook",id:"semver-for-models--edition-numbers-on-a-textbook",level:2},{value:"The two-tags story \u2014 the registry records history, not just winners",id:"the-two-tags-story--the-registry-records-history-not-just-winners",level:2},{value:"The registry landscape \u2014 Zot here, others in production",id:"the-registry-landscape--zot-here-others-in-production",level:2},{value:"What you&#39;ll do next, and the hand-off to M8",id:"what-youll-do-next-and-the-hand-off-to-m8",level:2}];function c(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"ship-the-model--kitops-oci-artifacts--signing",children:"Ship the Model \u2014 KitOps, OCI Artifacts & Signing"})}),"\n",(0,n.jsx)(t.admonition,{title:"Time",type:"info",children:(0,n.jsx)(t.p,{children:"Lesson video ~35 min \xb7 Lab ~45\u201360 min hands-on, depending on your machine."})}),"\n",(0,n.jsxs)(t.p,{children:["Here is the situation this module is built for. It is your on-call week, and the payments service is degraded. You bring up OpsMate to help you work the incident, and it answers from a model file on the serving box. Then a teammate asks the question you cannot answer: ",(0,n.jsx)(t.em,{children:"which"})," model is that, exactly? Is it the base Qwen you started with, or the tuned one from M6 that lost the measurement and was never supposed to ship? Who put that file on the server? Has anyone changed it since? You look, and the honest answer is a filename \u2014 ",(0,n.jsx)(t.code,{children:"opsmate-tuned-q8_0.gguf"}),' \u2014 sitting in a directory, with no version, no record of where its bytes came from, and no way to prove it is the file anyone signed off on. During a real incident, "I think it is the right model" is not an answer you want to give.']}),"\n",(0,n.jsxs)(t.p,{children:["That is the gap this module closes. Through M6 the model has been a ",(0,n.jsx)(t.strong,{children:"loose file"})," \u2014 copied onto the box, swapped by changing an env var, versioned by nothing more than its name. That was fine while you were the only person touching it on your own laptop. It stops being fine the moment the model is something a team serves in production, because a loose file cannot answer the three questions that matter when something goes wrong: ",(0,n.jsx)(t.em,{children:"what version is this, where did it come from, and has it been tampered with?"})," This module turns the model from a file into an ",(0,n.jsx)(t.strong,{children:"artifact"})," \u2014 versioned, addressable, and signed \u2014 so those three questions have answers you can prove."]}),"\n","\n",(0,n.jsx)(o.A,{src:"decks/m7-concepts.html",title:"M7 \u2014 Ship the Model: KitOps, OCI Artifacts & Signing"}),"\n",(0,n.jsx)(t.h2,{id:"why-a-filename-is-not-a-version--the-courier-without-a-manifest",children:"Why a filename is not a version \u2014 the courier without a manifest"}),"\n",(0,n.jsxs)(t.p,{children:['Think about how a parcel moves through a courier network. A parcel with just a name scrawled on the side \u2014 "Gourav\'s box" \u2014 is a problem the moment it leaves your hands. Nobody down the line knows what is inside, whether it is the box you meant to send, or whether someone opened it in transit and swapped the contents. A parcel that travels properly carries a ',(0,n.jsx)(t.strong,{children:"manifest"}),": a label that states exactly what is inside, a tracking number that is unique to ",(0,n.jsx)(t.em,{children:"this"})," parcel and no other, and a tamper-evident seal so the recipient can tell if it was opened on the way. The name is for humans; the manifest is what makes the parcel trustworthy across a chain of hands nobody in it fully controls."]}),"\n",(0,n.jsxs)(t.p,{children:["Copying a model file onto a server is shipping the parcel with a name and nothing else. It works right up until the model passes through more than one pair of hands \u2014 a build step, a registry, a deploy, a rollback \u2014 and then every one of those handoffs is a place where you can no longer say for certain what you are serving. The fix is the same as the courier's: give the model a manifest. That is what the rest of this module builds \u2014 a way to package the model with a label of exactly what is inside, a unique address that names ",(0,n.jsx)(t.em,{children:"these"})," bytes and no others, and a seal that proves nobody changed them."]}),"\n",(0,n.jsx)(t.h2,{id:"what-a-model-actually-is-on-disk-one-recap-not-a-re-teach",children:"What a model actually is on disk (one recap, not a re-teach)"}),"\n",(0,n.jsxs)(t.p,{children:["You already know this from M2, so this is a callback, not a lesson. A model on disk is not one thing \u2014 it is a small bundle of files that only mean something together: the ",(0,n.jsx)(t.strong,{children:"weights"})," (the giant pile of numbers, the bulk of the bytes), the ",(0,n.jsx)(t.strong,{children:"tokenizer"})," (how text becomes token IDs), the ",(0,n.jsx)(t.strong,{children:"config"})," (the architecture and hyperparameters the runtime needs to load it), and, for a chat model, the ",(0,n.jsx)(t.strong,{children:"chat template"}),' (how turns get serialized into the string the model sees). In the GGUF format you have been serving, those are packed into a single file; in the safetensors format you trained from in M6, they are a directory of files. Either way, "the model" is that bundle.']}),"\n",(0,n.jsxs)(t.p,{children:["The packaging job of this module follows straight from that fact. If a model is a bundle of related files, then shipping it well means shipping the ",(0,n.jsx)(t.em,{children:"whole"})," bundle as one versioned unit \u2014 not just the weights, but the things that were true ",(0,n.jsx)(t.em,{children:"about"})," this model when it was built: the prompts it expects, and the eval set it was measured on. A model artifact that carries its own eval set is an audit trail made physical: anyone who pulls it can re-run the measurement instead of trusting a number in a report."]}),"\n",(0,n.jsx)(t.h2,{id:"oci-artifacts-and-layers--the-shipping-container-with-a-manifest",children:"OCI artifacts and layers \u2014 the shipping container with a manifest"}),"\n",(0,n.jsxs)(t.p,{children:['The good news is you do not need a new system to ship models. The container world already solved "package a bundle of files, address it by a unique ID, push and pull it from a registry, and verify it did not change" \u2014 that is what a container image is. The standard underneath container images, the ',(0,n.jsx)(t.strong,{children:"OCI"})," (Open Container Initiative) format, turned out to be general enough to package ",(0,n.jsx)(t.em,{children:"anything"}),", not just container filesystems. A thing packaged that way is an ",(0,n.jsx)(t.strong,{children:"OCI artifact"}),", and a model packaged as an OCI artifact rides the exact same rails your container images already do: the same registries, the same push/pull, the same digests."]}),"\n",(0,n.jsx)(t.p,{children:"The analogy is a standardized shipping container. The reason a shipping container can move from a truck to a train to a ship to a crane at any port on earth is that its dimensions and fittings are standardized \u2014 every crane knows how to lift it without knowing or caring what is inside. OCI is that standard for software artifacts. Package your model as an OCI artifact and every registry, every CI system, every cluster that already speaks OCI can handle it, sight unseen. You are not inventing a model-distribution system; you are putting the model in the container everyone already knows how to move."}),"\n",(0,n.jsxs)(t.p,{children:["Inside the container, the goods are not one solid mass \u2014 they are separately-listed ",(0,n.jsx)(t.strong,{children:"crates"}),", and the container's manifest lists each one. In OCI those crates are ",(0,n.jsx)(t.strong,{children:"layers"}),", and this is the single most important structural idea in the module. A model artifact is not one opaque blob; it is a set of layers, each with its own content address, listed in a manifest. OpsMate's model kit has three:"]}),"\n",(0,n.jsx)(t.mermaid,{value:'flowchart TB\n  M["<b>manifest</b><br/>the packing list \u2014 names every layer<br/>by its digest, media type, and size"]\n  M --\x3e L1["<b>model layer</b> ~610 MB<br/>the GGUF weights<br/>(the heavy crate)"]\n  M --\x3e L2["<b>dataset layer</b> ~16 KB<br/>the golden eval set<br/>(a light crate)"]\n  M --\x3e L3["<b>code layer</b> ~5 KB<br/>the versioned prompts<br/>(a light crate)"]'}),"\n",(0,n.jsxs)(t.p,{children:["Read the sizes, because the whole point is in them. The model layer is hundreds of megabytes; the dataset and code layers are kilobytes. Because each is a separately-addressed crate, you can take ",(0,n.jsx)(t.strong,{children:"one crate without unloading the whole ship"}),' \u2014 pull just the prompts layer without dragging the 610 MB of weights along with it. That is not a party trick; it is how a cluster pulls a model\'s config to inspect it before deciding whether to pull the weights, and how you update the prompts a model ships with by replacing a 5 KB layer instead of re-uploading everything. Layers are why "the model plus its metadata" is one artifact but not one indivisible lump.']}),"\n",(0,n.jsx)(t.h2,{id:"modelkit-and-the-kitfile--a-dockerfile-for-models",children:"ModelKit and the Kitfile \u2014 a Dockerfile for models"}),"\n",(0,n.jsxs)(t.p,{children:["You have a tool for this, and it will feel familiar. ",(0,n.jsx)(t.strong,{children:"KitOps"})," packages a model bundle as an OCI artifact it calls a ",(0,n.jsx)(t.strong,{children:"ModelKit"}),", and you describe what goes in the kit with a ",(0,n.jsx)(t.strong,{children:"Kitfile"})," \u2014 which is to a ModelKit exactly what a Dockerfile is to a container image: a plain text manifest that names the pieces, read by a ",(0,n.jsx)(t.code,{children:"pack"})," command that builds the artifact."]}),"\n",(0,n.jsxs)(t.p,{children:["Here is the honest positioning, because you should know what you are adopting. KitOps is a ",(0,n.jsx)(t.strong,{children:"CNCF Sandbox"})," project \u2014 real, open, and OCI-native, but early-stage, not a graduated CNCF project like Kubernetes or Prometheus. Its ",(0,n.jsx)(t.code,{children:"kit"})," CLI is what this lab uses because it makes the layer story concrete and it packs to any OCI registry. There is also an emerging ",(0,n.jsx)(t.strong,{children:"interchange"})," effort \u2014 ",(0,n.jsx)(t.strong,{children:"ModelPack"})," \u2014 aiming to standardize the ",(0,n.jsx)(t.em,{children:"media types"})," a model artifact uses so that kits from different tools can be read by any of them; the Deep Dive reads the real media types and shows where that standardization is headed. The thing to take away is that this is a moving space: the ",(0,n.jsx)(t.em,{children:"concept"})," \u2014 a model as a layered, versioned OCI artifact \u2014 is durable and vendor-neutral; the specific tool is a current, reasonable choice, not a permanent commitment."]}),"\n",(0,n.jsx)(t.p,{children:"A Kitfile is short. Every top-level section becomes a layer:"}),"\n",(0,n.jsx)(t.mermaid,{value:'flowchart LR\n  K["<b>Kitfile</b><br/>(the packing list you write)"]\n  K --\x3e|"model:"| A["model layer<br/>the GGUF"]\n  K --\x3e|"datasets:"| B["dataset layer<br/>golden.yaml"]\n  K --\x3e|"code:"| C["code layer<br/>prompts/"]\n  A --\x3e P["<b>kit pack</b> \u2192 one OCI artifact"]\n  B --\x3e P\n  C --\x3e P\n  P --\x3e|"kit push"| R[("OCI registry<br/>(Zot)")]'}),"\n",(0,n.jsxs)(t.p,{children:["One rule the lab makes you feel deliberately: ",(0,n.jsx)(t.strong,{children:"every path in a Kitfile is relative"}),", never absolute. An artifact has to be portable \u2014 a path like ",(0,n.jsx)(t.code,{children:"/Users/you/models/..."})," only exists on your machine, so ",(0,n.jsx)(t.code,{children:"kit pack"})," rejects it. The pack context (the directory the Kitfile sits in) is the root everything resolves against, the same way a Docker build context works. You will hit the absolute-path error on purpose in the lab, because reading the error once is how you remember the rule."]}),"\n",(0,n.jsx)(t.h2,{id:"push-pull-and-the-crate-you-actually-want",children:"Push, pull, and the crate you actually want"}),"\n",(0,n.jsxs)(t.p,{children:["Once packed, a ModelKit moves like any OCI artifact: ",(0,n.jsx)(t.code,{children:"kit push"})," sends it to a registry, ",(0,n.jsx)(t.code,{children:"kit pull"})," brings it back. The move that matters is ",(0,n.jsx)(t.strong,{children:"selective pull"})," \u2014 retrieving one layer without the others. Because the manifest lists each layer by digest, the client can fetch exactly the crate you ask for. Want just the prompts a model ships with? ",(0,n.jsx)(t.code,{children:"kit unpack --filter=code"}),' pulls the 5 KB code layer and leaves the 610 MB of weights on the registry. You will do this live: unpack only the prompts and watch a few kilobytes arrive where a naive "download the model" would have moved half a gigabyte. That is the layer lesson stops being abstract.']}),"\n",(0,n.jsx)(t.h2,{id:"signing--the-wax-seal-not-the-locked-box",children:"Signing \u2014 the wax seal, not the locked box"}),"\n",(0,n.jsxs)(t.p,{children:['Packaging answers "what is inside" and "how do I address it." It does not answer "did anyone tamper with it." For that you ',(0,n.jsx)(t.strong,{children:"sign"})," the artifact, and it is worth being precise about what signing does and does not do, because the word misleads people."]}),"\n",(0,n.jsxs)(t.p,{children:["The analogy is a ",(0,n.jsx)(t.strong,{children:"wax seal"})," on a letter, pressed with a signet ring. The seal does not hide the letter \u2014 anyone can read it. What the seal does is prove two things: that the letter was sealed by whoever holds the ring (authenticity), and that nobody has opened it since (integrity). Break the seal and it cannot be re-formed without the ring. Signing a model artifact is exactly this: it is ",(0,n.jsx)(t.strong,{children:"tamper-evidence, not secrecy."})," A signed model is not encrypted or hidden; anyone can pull it. What the signature proves is that the person with the signing key vouched for ",(0,n.jsx)(t.em,{children:"these exact bytes"}),", and that the bytes have not changed since. If someone swaps the weights after signing, verification fails \u2014 the seal is broken."]}),"\n",(0,n.jsxs)(t.p,{children:["The precision that makes this work is that a signature is bound to a ",(0,n.jsx)(t.strong,{children:"digest"}),", not a tag. A tag like ",(0,n.jsx)(t.code,{children:"1.0.0"})," is a human-friendly label that someone can move to point at different bytes tomorrow; a digest like ",(0,n.jsx)(t.code,{children:"sha256:acbf90cc\u2026"})," ",(0,n.jsx)(t.em,{children:"is"})," the bytes \u2014 it is a cryptographic hash of the exact content, and it cannot point at anything else. So you always sign and verify by digest. This module uses ",(0,n.jsx)(t.strong,{children:"Cosign"})," (the Sigstore signing tool) with a local key pair: ",(0,n.jsx)(t.code,{children:"cosign generate-key-pair"})," makes the keys, ",(0,n.jsx)(t.code,{children:"cosign sign"})," seals the artifact by its digest, ",(0,n.jsx)(t.code,{children:"cosign verify"})," checks the seal. Keep the private key secret \u2014 it is your signet ring; anyone who has it can sign as you."]}),"\n",(0,n.jsx)(t.mermaid,{value:'flowchart LR\n  A["model artifact<br/>digest sha256:acbf\u2026"] --\x3e|"cosign sign --key cosign.key"| S["signature<br/>bound to that digest"]\n  S --\x3e|"stored beside the artifact<br/>in the registry"| R[("registry")]\n  R --\x3e|"cosign verify --key cosign.pub"| V{"bytes unchanged<br/>AND signed by<br/>the key holder?"}\n  V --\x3e|yes| OK["\u2713 safe to deploy"]\n  V --\x3e|no / no signature| NO["\u2717 refuse to deploy"]'}),"\n",(0,n.jsxs)(t.p,{children:["That bottom branch \u2014 ",(0,n.jsx)(t.em,{children:"no signature means refuse to deploy"})," \u2014 is the whole reason to sign. It is not paperwork; it is a gate. Later in this module you wire it into the preflight: with a flag set, OpsMate refuses to start unless the model it is about to serve has a valid signature. In M8 that same check becomes a Kubernetes admission policy on the cluster. Signing is only useful if something downstream ",(0,n.jsx)(t.em,{children:"verifies before it runs"})," \u2014 a seal nobody checks is decoration."]}),"\n",(0,n.jsx)(t.h2,{id:"semver-for-models--edition-numbers-on-a-textbook",children:"Semver for models \u2014 edition numbers on a textbook"}),"\n",(0,n.jsxs)(t.p,{children:["A version number should tell you what changed without making you diff two artifacts. Software uses ",(0,n.jsx)(t.strong,{children:"semantic versioning"})," \u2014 ",(0,n.jsx)(t.code,{children:"MAJOR.MINOR.PATCH"})," \u2014 and it carries over to models with one honest caveat: the field has no universal standard for what bumps what, so you adopt a ",(0,n.jsx)(t.em,{children:"convention"})," and state it. The convention this course uses:"]}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"MAJOR"})," \u2014 the model's capability changed in a way that could break callers: new base model, a retrain that shifts behaviour, a different architecture. Treat it like an API break."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"MINOR"})," \u2014 the model improved compatibly: a better tune on the same base, measurably better on your evals, same interface."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"PATCH"})," \u2014 nothing about the weights changed; you updated the ",(0,n.jsx)(t.em,{children:"packaging"})," \u2014 a new prompt template, a corrected eval set, fixed metadata."]}),"\n"]}),"\n",(0,n.jsxs)(t.p,{children:["The analogy is ",(0,n.jsx)(t.strong,{children:"editions of a textbook"}),". A new edition (major) reorganizes chapters and changes content \u2014 your old page references break. A revised printing (minor) fixes and improves within the same edition \u2014 same structure, better content. A corrected reprint (patch) fixes typos \u2014 the words on the page are unchanged, the errata are not. Reading ",(0,n.jsx)(t.code,{children:"1.0.0"})," versus ",(0,n.jsx)(t.code,{children:"2.0.0"})," versus ",(0,n.jsx)(t.code,{children:"1.1.0"})," tells a downstream consumer whether they can drop in the new model blindly (patch), should re-test (minor), or must treat it as a breaking change (major) \u2014 the same signal semver gives an API consumer."]}),"\n",(0,n.jsxs)(t.p,{children:["The one addition models borrow from software is the ",(0,n.jsx)(t.strong,{children:"pre-release suffix"})," \u2014 ",(0,n.jsx)(t.code,{children:"1.0.0-candidate"}),". A ",(0,n.jsx)(t.code,{children:"-candidate"})," build is one that exists, is real, is packaged and pushed \u2014 but has ",(0,n.jsx)(t.em,{children:"not"})," been promoted to the plain ",(0,n.jsx)(t.code,{children:"1.0.0"})," release. It is a version you can point at, measure, and talk about precisely, without it being the thing that ships. That suffix is the hinge of this module's story."]}),"\n",(0,n.jsx)(t.h2,{id:"the-two-tags-story--the-registry-records-history-not-just-winners",children:"The two-tags story \u2014 the registry records history, not just winners"}),"\n",(0,n.jsxs)(t.p,{children:["This is the spine of the module, and it comes straight out of M6. In M6 you did something disciplined: you tuned a model, measured it honestly against the committed baseline, and it ",(0,n.jsx)(t.strong,{children:"lost"})," \u2014 the tuned model scored worse on the golden set than the RAG baseline, so it did not ship. That was the right call. But here is the question packaging forces: what happens to that tuned model ",(0,n.jsx)(t.em,{children:"now"}),"? A loose-file world has two bad answers \u2014 delete it (and lose the record that you tried), or leave it lying in a directory (and risk someone serving it by accident). Versioning gives you a third, honest answer."]}),"\n",(0,n.jsxs)(t.p,{children:["You push ",(0,n.jsx)(t.strong,{children:"both"})," models, as two tags of the same repository:"]}),"\n",(0,n.jsx)(t.mermaid,{value:'flowchart TB\n  subgraph REPO["opsmate/model \u2014 one repository, two tags"]\n    T1["<b>1.0.0</b><br/>base Qwen3-0.6B<br/>the baseline holder \u2014 what SERVES<br/>SIGNED \u2713"]\n    T2["<b>1.0.0-candidate</b><br/>M6 tuned model<br/>measured, LOST, recorded<br/>NOT signed \u2014 will not pass the gate"]\n  end\n  T1 --\x3e|"carries"| G1["its golden set<br/>+ prompts"]\n  T2 --\x3e|"carries"| G2["the SAME golden set<br/>it was measured on"]\n  T1 --\x3e DEPLOY["signature gate: deploys"]\n  T2 --\x3e BLOCK["signature gate: blocked"]'}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:(0,n.jsx)(t.code,{children:"opsmate/model:1.0.0"})})," is the base model \u2014 the one that actually serves, the baseline holder. You sign it, and it passes the deploy gate."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:(0,n.jsx)(t.code,{children:"opsmate/model:1.0.0-candidate"})})," is the M6 tuned model \u2014 measured, lost, and recorded as exactly that. You deliberately do ",(0,n.jsx)(t.strong,{children:"not"})," sign it, so when the verify-before-deploy gate runs against it, it fails. The candidate is preserved and addressable, but it cannot be served by accident, because it was never sealed for release."]}),"\n"]}),"\n",(0,n.jsxs)(t.p,{children:['Each kit carries the golden set it was measured on, so the comparison is not a claim in a document \u2014 it is reproducible from the artifacts themselves. This is what "the registry records history, not just winners" means. A month from now, when someone asks "did we ever try tuning this?", the answer is not a Slack search \u2014 it is ',(0,n.jsx)(t.code,{children:"kit list opsmate/model"}),", and there is the candidate, with the eval set it was weighed on, and the fact that it was never signed for release telling you how it turned out. That is an ",(0,n.jsx)(t.strong,{children:"audit trail"})," made of artifacts instead of memory."]}),"\n",(0,n.jsx)(t.h2,{id:"the-registry-landscape--zot-here-others-in-production",children:"The registry landscape \u2014 Zot here, others in production"}),"\n",(0,n.jsxs)(t.p,{children:["The registry is where artifacts live, and you have choices. This lab runs ",(0,n.jsx)(t.strong,{children:"Zot"})," \u2014 a lightweight, OCI-native, CNCF registry \u2014 because it starts in seconds, needs no cloud account, and stores OCI artifacts (including ModelKits and their signatures) correctly, which is all the lab needs. It is a genuinely good choice for local and self-hosted use, not a toy."]}),"\n",(0,n.jsxs)(t.p,{children:["In production you would likely meet one of these instead, and the point is that ",(0,n.jsx)(t.em,{children:"your artifact does not change"})," \u2014 only where it is stored does:"]}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Harbor"})," \u2014 the common self-hosted enterprise registry (CNCF graduated): adds projects, RBAC, replication, vulnerability scanning, and signing-policy enforcement on top of OCI storage."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Artifactory / cloud registries"})," (JFrog, AWS ECR, GCP Artifact Registry, GHCR) \u2014 managed registries you already use for container images; because ModelKits are OCI artifacts, they push to these unchanged."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Hugging Face Hub"})," \u2014 the model-native distribution channel most teams pull ",(0,n.jsx)(t.em,{children:"base"})," models from. It is git-LFS-based rather than pure-OCI, so it is the odd one out structurally, but it is where the open-model supply chain starts."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"The through-line: because you packaged the model as an OCI artifact, moving from Zot to Harbor to ECR is a change of address, not a change of format. That portability is the payoff of not inventing your own model-distribution scheme."}),"\n",(0,n.jsx)(t.h2,{id:"what-youll-do-next-and-the-hand-off-to-m8",children:"What you'll do next, and the hand-off to M8"}),"\n",(0,n.jsxs)(t.p,{children:["In the lab you grow the compose stack one last time \u2014 adding the Zot ",(0,n.jsx)(t.strong,{children:"registry"})," service beside the model, app, and ui \u2014 and then you turn OpsMate's model into an artifact end to end. You author the Kitfile block by block (and hit the absolute-path error on purpose), pack and push ",(0,n.jsx)(t.strong,{children:"both"})," tags, package the M6 adapter as its own tiny kit to feel how light adapters travel, pull just the prompts layer to see selective pull live, and then sign the base by digest and verify it \u2014 while deliberately leaving the candidate unsigned so you watch the verify-before-deploy gate reject it. You wire that gate into the preflight, and you read the whole thing in the X-Ray Artifacts lens."]}),"\n",(0,n.jsxs)(t.p,{children:["This is the last module of the Compose phase, and it sets up the next one precisely. Everything M8 does \u2014 running OpsMate on Kubernetes with a real serving engine \u2014 begins with the cluster ",(0,n.jsx)(t.strong,{children:"pulling the model from a registry"}),". You just built that registry and put a signed, versioned model in it. M8's cluster pulls ",(0,n.jsx)(t.code,{children:"opsmate/model:1.0.0"})," from here, verifies its signature before admitting it, and serves it. The loose file is gone; from here on, the model is an artifact with a version, an address, and a seal \u2014 which is exactly what it needs to be to run in production."]})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},7684(e,t,s){s.d(t,{A:()=>a});var i=s(4848);s(6540);var n=s(6497);function a({src:e,title:t="Slides"}){let s=(0,n.Ay)(e);return(0,i.jsxs)("div",{className:"deck_nWXz",children:[(0,i.jsxs)("div",{className:"bar_dOoE",children:[(0,i.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,i.jsx)("a",{className:"full_PrDQ",href:s,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,i.jsx)("div",{className:"frame_M4DO",children:(0,i.jsx)("iframe",{src:s,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,s){s.d(t,{R:()=>o,x:()=>r});var i=s(6540);let n={},a=i.createContext(n);function o(e){let t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);